SELECT * FROM (SELECT e.event_id,'INST:'||s.instruction_id case_id,e.activity,e.timestamp FROM (SELECT 'INST:'||instruction_id event_id,'Rolling Instruction Issued' activity,issued_at timestamp,instruction_id source_key FROM rolling_instruction WHERE issued_at IS NOT NULL AND (1=1)) e JOIN rolling_instruction s ON s.instruction_id=e.source_key UNION ALL SELECT e.event_id,'INST:'||m.instruction_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Heating Completed' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='A')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id UNION ALL SELECT e.event_id,'INST:'||m.instruction_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Finish Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='F')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.material_id) ORDER BY case_id,timestamp,event_id;
